def minPath(grid, k):
    N = len(grid)
    if N == 1:
        return [grid[0][0]] * k

    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    def in_bounds(x, y):
        return 0 <= x < N and 0 <= y < N

    from functools import lru_cache

    @lru_cache(None)
    def dfs(x, y, steps_left):
        if steps_left == 0:
            return [grid[x][y]]

        min_path = [float('inf')] * (k - steps_left + 1)

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if in_bounds(nx, ny):
                possible_path = dfs(nx, ny, steps_left - 1)
                path = [grid[x][y]] + possible_path
                if path < min_path:
                    min_path = path

        return min_path

    min_overall_path = [float('inf')] * k

    for i in range(N):
        for j in range(N):
            path = dfs(i, j, k - 1)
            if path < min_overall_path:
                min_overall_path = path

    return min_overall_path
