        paths = []
        # Initialize paths with all possible starting positions
        for i in range(N):
            for j in range(N):
                paths.append([(i, j)])

        for _ in range(k - 1):
            new_paths = []
            for path in paths:
                x, y = path[-1]
                for dx, dy in directions:
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < N and 0 <= ny < N:
                        new_paths.append(path + [(nx, ny)])
            paths = new_paths

        min_path = min(paths, key=sort_key)
        return sort_key(min_path)

    return find_min_path()
